import { contract } from '@stellar/stellar-sdk'
import { WAIT_MARGIN_MS } from './config.ts'
import { TransactionError, invocationError, type CallTarget } from './errors.ts'
import { CLOSED, MARKER } from './internal.ts'
import type { Account } from './account.ts'
import type { Worker } from './worker.ts'

/**
 * A contract client generated by `stellar contract bindings typescript`: a
 * `contract.Client` subclass whose constructor takes only the options (its
 * spec is built in).
 */
export type BindingsClass<C extends contract.Client = contract.Client> = new (options: contract.ClientOptions) => C

/**
 * The SDK's contract client built from the contract's spec, without
 * generated types: one method per contract function, each taking a
 * named-args object and returning an `AssembledTransaction`.
 */
export type ContractClient = contract.Client & { [method: string]: any }

/** A contract's Wasm, and the client generated for it when there is one: declared once, used everywhere. */
export interface ContractDefinition<C extends contract.Client = ContractClient> {
  readonly file: string | URL
  readonly client: BindingsClass<C> | undefined
}

/**
 * Declares a contract once: its Wasm file and, optionally, the client
 * `stellar contract bindings typescript` generated for it. List it in a
 * suite's `wasm`, deploy it with `account.deploy(Storage)`, attach to it
 * with `worker.contract(id, Storage)`: each gives that client, typed. It is
 * the only way to pair a generated client with a contract.
 */
export function defineContract(file: string | URL): ContractDefinition<ContractClient>
export function defineContract<C extends contract.Client>(file: string | URL, client: BindingsClass<C>): ContractDefinition<C>
export function defineContract(file: string | URL, client?: BindingsClass): ContractDefinition<contract.Client> {
  return Object.freeze({ file, client })
}

export function isDefinition(value: unknown): value is ContractDefinition<any> {
  return typeof value === 'object' && value !== null && !(value instanceof URL) && !(value instanceof Uint8Array) && 'file' in value
}

/** The options `signAndSend` takes. */
export type SendOptions = NonNullable<Parameters<contract.AssembledTransaction<unknown>['signAndSend']>[0]>

/**
 * Signs and sends a call, and waits for its result: `await
 * send(storage.put_persist({ key: 1, val: 7 }))` is `await (await
 * storage.put_persist(…)).signAndSend()`. Returns the SDK's
 * SentTransaction, its `result` typed as the method's.
 */
export async function send<T>(
  tx: contract.AssembledTransaction<T> | Promise<contract.AssembledTransaction<T>>,
  options?: SendOptions,
): Promise<contract.SentTransaction<T>> {
  return (await tx).signAndSend(options)
}

/**
 * The upper time bound of the transactions a client builds (the SDK's
 * default is 300 s from the wall clock). Far ahead, so moving ledger time
 * forward (setTime) never makes them too late. How long to wait for a sent
 * transaction is separate: the worker's `waitSeconds`.
 */
export const CLIENT_TIMEOUT_SECONDS = 10 * 365 * 24 * 3600

/** How long to wait for sent transactions, where, and what cancels the wait. */
export interface WaitContext {
  environment: string
  /** At most this long polling for a sent transaction's result. */
  waitSeconds: number
  /** Aborted when the worker is torn down: any wait still running is cancelled. */
  readonly [CLOSED]: AbortSignal
}

const BOUND = Symbol('soroban-sim-vitest/client')

/** What the harness keeps about a client it built. */
interface Bound {
  worker: Worker
  wasmHash: string | undefined
  signer: Account | undefined
  Bindings: BindingsClass | undefined
}

/** Specs by Wasm hash, shared across workers: a hash names the same code everywhere. */
const specs = new Map<string, Promise<contract.Spec>>()

export function rememberSpec(wasmHash: string, wasm: Uint8Array): void {
  if (!specs.has(wasmHash)) specs.set(wasmHash, Promise.resolve(contract.Spec.fromWasm(Buffer.from(wasm))))
}

/** The contract's Wasm hash (hex), or undefined for a Stellar asset contract. */
export async function wasmHashOf(worker: Worker, contractId: string): Promise<string | undefined> {
  const { executable } = await worker.rpc.getContractInstance(contractId)
  return executable.type === 'contractExecutableWasm' ? Buffer.from(executable.wasmHash.value).toString('hex') : undefined
}

/** The spec of the code `wasmHash` names (from the network if this process has not seen it). */
export function specFor(worker: Worker, wasmHash: string): Promise<contract.Spec> {
  let found = specs.get(wasmHash)
  if (!found) {
    found = worker.rpc.getContractWasmByHash(wasmHash, 'hex').then((wasm) => contract.Spec.fromWasm(Buffer.from(wasm)))
    found.catch(() => specs.delete(wasmHash))
    specs.set(wasmHash, found)
  }
  return found
}

/**
 * The options a client on `worker` takes, signed by `signer` (or unsigned,
 * for reads). The SDK passes a client's options to every method it builds,
 * so the method option `timeoutInSeconds` set here applies to all of them.
 */
export function clientOptions(
  worker: Worker,
  contractId: string,
  signer: Account | undefined,
): contract.ClientOptions & contract.MethodOptions {
  return {
    contractId,
    rpcUrl: worker.rpcUrl,
    allowHttp: worker.rpcUrl.startsWith('http:'),
    networkPassphrase: worker.networkPassphrase,
    timeoutInSeconds: CLIENT_TIMEOUT_SECONDS,
    ...(signer ? { publicKey: signer.address, ...contract.basicNodeSigner(signer.keypair, worker.networkPassphrase) } : {}),
  }
}

/** Builds the client from a generated class, or `contract.Client` from a spec. */
export function buildClient(
  worker: Worker,
  contractId: string,
  wasmHash: string | undefined,
  signer: Account | undefined,
  from: BindingsClass | contract.Spec,
): ContractClient {
  const options = clientOptions(worker, contractId, signer)
  const Bindings = typeof from === 'function' ? from : undefined
  const client = (typeof from === 'function' ? new from(options) : new contract.Client(from, options)) as ContractClient
  const bound: Bound = { worker, wasmHash, signer, Bindings }
  Object.defineProperty(client, BOUND, { value: bound })
  // In a setup's result the client is stored as a marker, and each test gets it back on its own network.
  Object.defineProperty(client, 'toJSON', {
    value: () => ({ [MARKER]: 'contract', id: contractId, wasmHash: wasmHash ?? null, signer: signer?.name ?? null }),
  })
  for (const fn of client.spec.funcs()) {
    const method = fn.name.toString()
    if (method === '__constructor' || typeof client[method] !== 'function') continue
    client[method] = typedErrors(client[method], { contract: contractId, method, spec: client.spec }, worker)
  }
  return client
}

/** What the harness knows about a client it built; undefined for any other client. */
export function boundOf(client: contract.Client): Bound | undefined {
  return (client as unknown as Record<symbol, Bound | undefined>)[BOUND]
}

type Method = (...args: any[]) => Promise<contract.AssembledTransaction<unknown>>

/**
 * The same method, whose transaction throws the harness's typed errors
 * where the SDK's would throw them: reading `result` and `signAndSend()`
 * (the SDK's error stays as `cause`). Everything else is the SDK's: it
 * builds, simulates, signs and sends.
 */
function typedErrors(original: Method, target: CallTarget, wait: WaitContext): Method {
  return async (...params: any[]) => {
    const tx = await original(...params)
    mapResult(tx, target)
    mapSignAndSend(tx, target, wait)
    return tx
  }
}

/** `tx.result`, throwing the typed error for a failed simulation. */
function mapResult(tx: contract.AssembledTransaction<unknown>, target: CallTarget): void {
  const getter = Object.getOwnPropertyDescriptor(contract.AssembledTransaction.prototype, 'result')?.get
  if (!getter) return
  Object.defineProperty(tx, 'result', {
    configurable: true,
    get() {
      try {
        return getter.call(tx)
      } catch (e) {
        throw typedError(target, tx, e)
      }
    },
  })
}

const CANCELLED = Symbol('cancelled')
const EXPIRED = Symbol('expired')

/**
 * `tx.signAndSend`, still the SDK's, with its failures typed and its wait
 * bounded on its own: the transaction is signed with the client's far time
 * bound (so time travel never makes it too late), and once it is sent the
 * SDK polls for at most `wait.waitSeconds`; a timer of the harness's own
 * ends the wait just after that whatever the SDK does. Tearing the worker
 * down cancels the wait. A transaction the network refuses, or one not applied in time,
 * is a TransactionError with its hash, method, environment and last status.
 */
export function mapSignAndSend(tx: contract.AssembledTransaction<unknown>, target: CallTarget, wait: WaitContext): void {
  const signAndSend = tx.signAndSend.bind(tx)
  const what = `${target.method} on ${target.contract}`
  tx.signAndSend = async ({ watcher, ...options }: Parameters<typeof signAndSend>[0] = {}) => {
    const validity = tx.options.timeoutInSeconds
    const details = { environment: wait.environment, hash: undefined as string | undefined, lastStatus: 'not sent' }
    let expire!: () => void
    const expired = new Promise<never>((_, reject) => (expire = () => reject(EXPIRED)))
    const untilExpiry = () => setTimeout(expire, wait.waitSeconds * 1000 + WAIT_MARGIN_MS)
    let timer = untilExpiry()
    const bounded: contract.Watcher = {
      onSubmitted(response) {
        details.hash = response?.hash
        details.lastStatus = response?.status ?? details.lastStatus
        // Signed by now, with the far time bound; from here the SDK only polls, as long as this says.
        tx.options.timeoutInSeconds = wait.waitSeconds
        clearTimeout(timer)
        timer = untilExpiry()
        watcher?.onSubmitted?.(response)
      },
      onProgress(response) {
        details.lastStatus = response?.status ?? details.lastStatus
        watcher?.onProgress?.(response)
      },
    }
    const sending = signAndSend({ ...options, watcher: bounded })
    sending.catch(() => {})
    let sent: contract.SentTransaction<unknown>
    try {
      sent = await Promise.race([sending, cancelled(wait[CLOSED]), expired])
    } catch (e) {
      if (e === CANCELLED) {
        throw new TransactionError(what, 'CANCELLED', undefined, details, 'the wait for its result was cancelled: the worker was torn down')
      }
      if (e === EXPIRED || e instanceof contract.SentTransaction.Errors.TransactionStillPending) {
        const why = `not applied within ${wait.waitSeconds} s of waiting`
        const error = new TransactionError(what, 'NOT_FOUND', undefined, details, why)
        throw e === EXPIRED ? error : Object.assign(error, { cause: e })
      }
      if (e instanceof contract.SentTransaction.Errors.SendFailed) {
        const result = /"result":\s*"(\w+)"/.exec(e.message)?.[1]
        const hash = /"hash":\s*"(\w+)"/.exec(e.message)?.[1] ?? details.hash
        throw Object.assign(new TransactionError(what, 'ERROR', result, { ...details, hash, lastStatus: 'ERROR' }), { cause: e })
      }
      throw typedError(target, tx, e)
    } finally {
      clearTimeout(timer)
      tx.options.timeoutInSeconds = validity
    }
    const response = sent.getTransactionResponse
    if (response?.status === 'FAILED') {
      const events = response.diagnosticEventsXdr ?? []
      if (events.length) throw invocationError(target, '', events)
      const result = response.resultXdr.result.type.replace(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`)
      throw new TransactionError(what, 'FAILED', result, { ...details, lastStatus: 'FAILED' })
    }
    return sent
  }
}

function cancelled(signal: AbortSignal): Promise<never> {
  return new Promise((_, reject) => {
    if (signal.aborted) reject(CANCELLED)
    else signal.addEventListener('abort', () => reject(CANCELLED), { once: true })
  })
}

/** Runs `step`, turning the SDK's simulation failure into an InvocationError or ContractError. */
export async function mapping<T>(target: CallTarget, tx: contract.AssembledTransaction<unknown>, step: () => Promise<T>): Promise<T> {
  try {
    return await step()
  } catch (e) {
    throw typedError(target, tx, e)
  }
}

function typedError(target: CallTarget, tx: contract.AssembledTransaction<unknown>, e: unknown): unknown {
  if (e instanceof contract.AssembledTransaction.Errors.SimulationFailed) {
    const text = /Transaction simulation failed: "([\s\S]*)"$/.exec(e.message)?.[1] ?? e.message
    const events = tx.simulation && 'events' in tx.simulation ? tx.simulation.events : []
    return Object.assign(invocationError(target, text, events), { cause: e })
  }
  return e
}
